LAT=fm('T = t_s + t_c + t_n + t_a; s = D - T',{'T':'worst-case end-to-end sequential latency','t_s':'sensing delay','t_c':'computation delay','t_n':'network delay','t_a':'actuation-interface delay','s':'deadline slack','D':'required deadline'},{k:'ms'for k in ['T','t_s','t_c','t_n','t_a','s','D']},['All supplied delays are worst-case upper bounds and execute sequentially without overlap.','Other delays are excluded by the supplied toy model.','Meeting this timing budget alone does not certify physical safety.'])
ask(1924,'physical-safety','Collision Avoidance hard-latency bullet','For a supplied sequential pipeline, sensing takes at most 4 ms and actuation-interface delay 6 ms. Edge computation takes 8 ms with no network delay; cloud computation takes 5 ms plus 30 ms network delay. With a 20 ms deadline, which timing assessment is correct?', [('Edge: 18 ms, meeting the deadline; cloud: 45 ms, missing it','Adding all sequential worst-case delays gives18 and45 ms; compute speed alone does not decide the end-to-end result.'),('Edge: 18 ms; cloud: 15 ms, so both meet the deadline','The15 ms cloud total omits its30 ms network delay.'),('Edge: 8 ms; cloud: 5 ms, so cloud has the better deadline guarantee','These are computation times alone, excluding sensing, communication and actuation-interface delays.')],kind='numerical',difficulty='medium',ass=LAT['assumptions'],steps=['Edge latency:4+8+0+6=18 ms, leaving20−18=2 ms slack.','Cloud latency:4+5+30+6=45 ms, leaving20−45=−25 ms slack.','Only the edge route meets the supplied20 ms bound; this is a toy timing calculation, not a certified safe robot.'],formulas=[LAT],cites=[(1934,'Cloud and edge compute architecture opportunity bullet')],conflict=SAFE)
