 q=QM[f'{B}-P{p}-Q{n:02}'];next(o for o in q['options']if o['id']==oid)['text']=text;q['solution']['optionExplanations'][oid]=('Correct. 'if oid in q['correctOptionIds']else'Incorrect. ')+why
